@Component("invoice-entity-projector")
public class InvoiceEntityProjector implements EntityProjector<Invoice>{
		
	// core constructor
	public InvoiceEntityProjector(ProjectorRegistry registry,
										InvoiceRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Invoice> getEntityClass() {
		return Invoice.class;
	}

    /*
	 * Insert a Invoice
	 * 
     * @param	entity Invoice
     */
    public Invoice create( Invoice entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Invoice
	 * 
     * @param	entity Invoice
     */
    public Invoice update( Invoice entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Invoice
	 * 
     * @param	id		UUID
     */
    public Invoice delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Invoice entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    

    /*
     * Assign a BillingAccount
     * 
     * @param	parentId	UUID
     * @param	assignment 	BillingAccount 
     * @return	Invoice
     */
    public Invoice assignBillingAccount( UUID parentId, BillingAccount assignment ) {
	    LOGGER.info("assigning BillingAccount as " + assignment.toString() );

	    Invoice parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( BillingAccount.class, assignment.getBillingAccountId());

	    // ------------------------------------------
		// assign the BillingAccount to the parent entity
		// ------------------------------------------ 
	    parentEntity.setBillingAccount( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the BillingAccount
	 * 
	 * @param	parentId		UUID
	 * @return	Invoice
	 */
	public Invoice unAssignBillingAccount( UUID parentId ) {
		Invoice parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning BillingAccount on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the BillingAccount on the parent entithy
		// ------------------------------------------     
	    parentEntity.setBillingAccount(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}

    /*
     * Assign a Policy
     * 
     * @param	parentId	UUID
     * @param	assignment 	Policy 
     * @return	Invoice
     */
    public Invoice assignPolicy( UUID parentId, Policy assignment ) {
	    LOGGER.info("assigning Policy as " + assignment.toString() );

	    Invoice parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Policy.class, assignment.getPolicyId());

	    // ------------------------------------------
		// assign the Policy to the parent entity
		// ------------------------------------------ 
	    parentEntity.setPolicy( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Policy
	 * 
	 * @param	parentId		UUID
	 * @return	Invoice
	 */
	public Invoice unAssignPolicy( UUID parentId ) {
		Invoice parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Policy on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Policy on the parent entithy
		// ------------------------------------------     
	    parentEntity.setPolicy(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the Payments
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Invoice
     */
    public Invoice addToPayments( UUID parentId, Payment addTo ) {
	    LOGGER.info("handling AssignPaymentsToInvoiceEvent - " );
	    
	    Invoice parentEntity = repository.findById(parentId).get();
	    Payment child = registry.project( Payment.class, addTo.getPaymentId());
	    
	    parentEntity.getPayments().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Payments
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Invoice
     */
	public Invoice removeFromPayments( UUID parentId, Payment removeFrom ) {
	    LOGGER.info("handling RemovePaymentsFromInvoiceEvent " );
	
	    Invoice parentEntity = repository.findById(parentId).get();
	    Payment child = registry.project( Payment.class, removeFrom.getPaymentId());
	    
	    parentEntity.getPayments().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Invoice via an FindInvoiceQuery
     * @return 	query	FindInvoiceQuery
     */
    @SuppressWarnings("unused")
    public Invoice find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Invoice - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Invoices
     *
     * @param	query	FindAllInvoiceQuery 
     * @return 	List<Invoice> 
     */
    @SuppressWarnings("unused")
    public List<Invoice> findAll( FindAllInvoiceQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Invoice - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final InvoiceRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(InvoiceEntityProjector.class.getName());

}
